{
  "name": "USB2FIR 远红外传感器接口模块",
  "name_en": "USB2FIR far-infrared sensor interface module",
  "manufacturer": "Melexis",
  "description": "该设备是用于连接远红外热传感器的 USB 接口模块，常见于 Melexis MLX 系列 FIR 传感器评估或数据采集场景。它支持通信测试、能力与状态查询、存储器读写、进入引导加载模式，以及批量读取与热帧初始化/更新等操作。",
  "description_en": "This device is a USB interface module for far-infrared thermal sensors, commonly used with Melexis MLX-series FIR sensors in evaluation or data acquisition setups. It supports communication tests, capability and status queries, memory read/write, bootloader entry, and bulk data readout plus thermal frame initialization and updates.",
  "actions": [
    {
      "action_name": "auto-echo_test",
      "description": "发送回显测试值以验证通信链路是否正常。",
      "description_en": "Transmit an echo test value to verify that the communication link is working."
    },
    {
      "action_name": "auto-get_capability",
      "description": "读取接口模块支持的功能能力位。",
      "description_en": "Read the capability bitfield that indicates which functions the interface module supports."
    },
    {
      "action_name": "auto-get_status",
      "description": "读取最近一次事务的状态。",
      "description_en": "Read the status of the most recent transaction."
    },
    {
      "action_name": "auto-start_bootloader",
      "description": "使设备跳转到引导加载模式，用于固件维护或升级。",
      "description_en": "Make the device jump to bootloader mode for firmware maintenance or updates."
    },
    {
      "action_name": "auto-read_memory",
      "description": "从指定起始地址读取一段设备存储器数据。",
      "description_en": "Read a block of device memory starting from a specified address."
    },
    {
      "action_name": "auto-write_memory",
      "description": "向指定起始地址写入一段设备存储器数据。",
      "description_en": "Write a block of data to device memory starting at a specified address."
    },
    {
      "action_name": "auto-bulkread",
      "description": "执行一次批量数据读取。",
      "description_en": "Perform a bulk data read operation."
    },
    {
      "action_name": "auto-start_bfmode",
      "description": "启动 BF 模式，并可设置刷新率。",
      "description_en": "Start BF mode, with an optional refresh rate setting."
    },
    {
      "action_name": "auto-stop_bfmode",
      "description": "停止 BF 模式。",
      "description_en": "Stop BF mode."
    },
    {
      "action_name": "auto-initializeFrame",
      "description": "初始化帧数据结构，并设置默认温度值。",
      "description_en": "Initialize the frame data structure and set a default temperature value."
    },
    {
      "action_name": "auto-updateFrame",
      "description": "使用新数据更新当前帧。",
      "description_en": "Update the current frame with new data."
    }
  ],
  "tag_hints": [
    "far-infrared sensing",
    "thermal imaging",
    "Melexis MLX",
    "USB sensor interface",
    "frame acquisition",
    "memory read/write",
    "firmware bootloader"
  ]
}

